using System.Collections.Immutable;

namespace ConfigurationSourceGen.Validations;

public sealed class RangeValidator : IGenerateValidator {
    public string AttributeName { get; } = "RangeAttribute";

    public string GenerateAttributeSource(string ns) => $$"""
        // <auto-generated/>
        namespace {{ns}};

        [global::System.AttributeUsage(global::System.AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
        public sealed class RangeAttribute : global::System.Attribute {
            public int Minimum { get; }
            public int Maximum { get; }

            public RangeAttribute(int minimum, int maximum) {
                Minimum = minimum;
                Maximum = maximum;
            }
        }
        """;


    public void Generate(CodeBuilder builder, ToGenerateProperty property, AttributeDefinition attribute, string valueExpression) {

        if (attribute.Arguments.Count < 2) {
            return;
        }

        if (!ValidationGeneratorHelper.TryGetIntArgument(attribute, 0, out int minimum) || 
            !ValidationGeneratorHelper.TryGetIntArgument(attribute, 1, out int maximum)
            ) {
            return;
        }

        builder.If($"{valueExpression} < {minimum} || {valueExpression} > {maximum}", () => {
            ValidationGeneratorHelper.AddError(
                builder,
                property.Name,
                $"must be between {minimum} and {maximum}.");
        });
    }
}